import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_min_clamp_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void fused_min_clamp_kernel(
    const float* __restrict__ in, 
    float* out, 
    const float min_val, 
    const float max_val, 
    const int size
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = in[idx];
        // Replicate: val = torch.min(val, min_val)
        val = fminf(val, min_val);
        // Replicate: val = torch.clamp(val, min_val, max_val)
        if (val < min_val) {
            val = min_val;
        } else if (val > max_val) {
            val = max_val;
        }
        out[idx] = val;
    }
}

torch::Tensor fused_min_clamp_cuda(torch::Tensor x, float min_val, float max_val) {
    auto out = torch::empty_like(x);
    int size = x.numel();

    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;

    fused_min_clamp_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(), 
        out.data_ptr<float>(), 
        min_val, 
        max_val, 
        size
    );

    return out;
}
"""

fused_min_clamp_cpp_source = r"""
torch::Tensor fused_min_clamp_cuda(torch::Tensor x, float min_val, float max_val);
"""

fused_min_clamp = load_inline(
    name="fused_min_clamp",
    cpp_sources=fused_min_clamp_cpp_source,
    cuda_sources=fused_min_clamp_source,
    functions=["fused_min_clamp_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that replaces the min+clamp sequence with a fused custom CUDA operator.
    """
    def __init__(self, in_channels, out_channels, kernel_size, groups, min_value, max_value, dropout_p):
        super().__init__()
        self.conv = nn.Conv3d(in_channels, out_channels, kernel_size)
        self.norm = nn.GroupNorm(groups, out_channels)
        self.dropout = nn.Dropout(dropout_p)
        self.min_value = float(min_value)
        self.max_value = float(max_value)
        self.fused_min_clamp = fused_min_clamp

    def forward(self, x):
        x = self.conv(x)
        x = self.norm(x)
        # Fused min+clamp
        x = self.fused_min_clamp.fused_min_clamp_cuda(x, self.min_value, self.max_value)
        x = self.dropout(x)
        return x
